import Foundation

/// Parses raw responses from the Server AI into structured `AgentMessage`s for the billing harness.
public struct LLMResponseParser {
    /// Parses the raw string generated by the AI into an `AgentMessage`.
    public static func parse(
        content: String,
        catalog: [Item],
        settings: AppSettings
    ) -> AgentMessage {
        var thought: String? = nil
        var cleanContent = content

        // 1. Extract thought process enclosed in <thought> tags
        if let thoughtStart = content.range(of: "<thought>"),
           let thoughtEnd = content.range(of: "</thought>") {
            let thoughtSubstr = content[thoughtStart.upperBound..<thoughtEnd.lowerBound]
            thought = String(thoughtSubstr).trimmingCharacters(in: .whitespacesAndNewlines)
            cleanContent.removeSubrange(thoughtStart.lowerBound..<thoughtEnd.upperBound)
        }

        // 2. Extract structured JSON payload from markdown fences or raw JSON
        var extractedJson: String? = nil
        var parsedPayload: AgentJsonPayload? = nil

        let jsonPattern = #"```(?:json)?\s*(\{[\s\S]*?\})\s*```"#
        if let regex = try? NSRegularExpression(pattern: jsonPattern, options: []),
           let match = regex.firstMatch(in: content, options: [], range: NSRange(location: 0, length: content.utf16.count)) {
            let range = match.range(at: 1)
            let jsonSub = (content as NSString).substring(with: range)
            extractedJson = jsonSub

            if let data = jsonSub.data(using: .utf8),
               let payload = try? JSONDecoder().decode(AgentJsonPayload.self, from: data) {
                parsedPayload = payload
            }
        } else if let openBrace = cleanContent.firstIndex(of: "{"),
                  let closeBrace = cleanContent.lastIndex(of: "}") {
            let rawSub = String(cleanContent[openBrace...closeBrace])
            if let data = rawSub.data(using: .utf8),
               let payload = try? JSONDecoder().decode(AgentJsonPayload.self, from: data) {
                extractedJson = rawSub
                parsedPayload = payload
            }
        }

        // 3. Extract user-facing message
        let displayText: String = {
            if let payload = parsedPayload, !payload.message.isEmpty {
                return payload.message
            }
            var text = cleanContent
            if let json = extractedJson {
                text = text.replacingOccurrences(of: "```json\n\(json)\n```", with: "")
                text = text.replacingOccurrences(of: "```\(json)```", with: "")
            }
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? "Order processed." : trimmed
        }()

        let status: AgentResponseStatus = (parsedPayload?.status == "needs_clarification") ? .needsClarification : .ready

        // 4. Compute financial bill summary from parsed items
        var billSummary: BillSummary? = nil
        if let items = parsedPayload?.items, !items.isEmpty {
            billSummary = BillCalculator.computeBill(
                from: items,
                catalog: catalog,
                currencySymbol: settings.currencySymbol,
                taxRatePercent: settings.taxRatePercent
            )
        }

        let hasAutoCorrection = parsedPayload?.items?.contains { $0.wasAutoCorrected == true } == true

        return AgentMessage(
            role: .agent,
            text: displayText,
            thoughtProcess: thought ?? parsedPayload?.thought,
            rawJsonOutput: extractedJson,
            status: status,
            billSummary: billSummary,
            parsedItems: parsedPayload?.items,
            pendingClarification: parsedPayload?.pendingClarification,
            hasAutoCorrection: hasAutoCorrection,
            unitCorrectionNotes: parsedPayload?.unitCorrections,
            canUndo: true
        )
    }
}
